mapper.select:
SELECT n.notice_id, n.title, n.important_yn, n.view_count, n.writer_id, u.user_name AS writer_name, n.created_at FROM notice n LEFT JOIN users u ON n.writer_id = u.user_id
ORDER BY n.important_yn DESC, n.created_at DESC, n.notice_id DESC
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO notice (
    notice_id, title, content, important_yn, view_count, use_yn, writer_id, created_at
) VALUES (
    #{noticeId}, #{title}, #{content}, #{importantYn}, 0, 'Y', #{writerId}, CURRENT_TIMESTAMP
)

mapper.update:
UPDATE notice
SET view_count = view_count + 1
WHERE notice_id = #{noticeId}
